-- Reconcile operational trigger chain
create or replace function public.validate_condominium_legal_case_scope() returns trigger language plpgsql set search_path='public' as $$ declare w uuid; begin select workspace_id into w from public.condominiums where id=new.condominium_id; if w is null then raise exception 'Il condominio indicato non esiste'; end if; if new.workspace_id<>w then raise exception 'Contenzioso e condominio devono appartenere allo stesso workspace'; end if; return new; end $$;
create or replace function public.validate_condominium_tax_scope() returns trigger language plpgsql set search_path='public' as $$ declare w uuid; begin select workspace_id into w from public.condominiums where id=new.condominium_id; if w is null then raise exception 'Il condominio indicato non esiste'; end if; if new.workspace_id<>w then raise exception 'Obbligo fiscale e condominio devono appartenere allo stesso workspace'; end if; return new; end $$;
create or replace function public.guard_confirmed_unit_transformation_immutable() returns trigger language plpgsql set search_path='' as $$ begin if old.status='Confermata' then raise exception 'CONFIRMED_TRANSFORMATION_IMMUTABLE: una trasformazione confermata è immodificabile'; end if; return case when tg_op='DELETE' then old else new end; end $$;
create or replace function public.guard_confirmed_unit_transformation_items_immutable() returns trigger language plpgsql set search_path='' as $$ begin if tg_op<>'INSERT' and exists(select 1 from public.condominium_unit_transformations where id=old.transformation_id and status='Confermata') then raise exception 'CONFIRMED_TRANSFORMATION_ITEMS_IMMUTABLE: i collegamenti genealogici confermati sono immodificabili'; end if; if tg_op<>'DELETE' and exists(select 1 from public.condominium_unit_transformations where id=new.transformation_id and status='Confermata') then raise exception 'CONFIRMED_TRANSFORMATION_ITEMS_IMMUTABLE: i collegamenti genealogici confermati sono immodificabili'; end if; return case when tg_op='DELETE' then old else new end; end $$;
create or replace function public.require_trusted_unit_transformation_confirmation() returns trigger language plpgsql set search_path='' as $$ begin if new.status='Confermata' and (tg_op='INSERT' or old.status is distinct from 'Confermata') and current_user<>'postgres' then raise exception 'UNIT_TRANSFORMATION_CONFIRMATION_REQUIRES_TRUSTED_RPC: la conferma deve avvenire tramite una procedura transazionale autorizzata'; end if; return new; end $$;
create or replace function public.validate_confirmed_unit_transformation_genealogy() returns trigger language plpgsql set search_path='' as $$ declare s int; d int; v int; u int; a int; b int; begin if new.status<>'Confermata' then return new; end if; select count(*) filter(where i.direction='Fonte')::int,count(*) filter(where i.direction='Destinazione')::int,count(*) filter(where x.id is not null and x.workspace_id=new.workspace_id and x.condominium_id=new.condominium_id)::int,count(distinct i.unit_id)::int,count(*) filter(where i.direction='Fonte' and x.lifecycle_status='Attiva' and x.workspace_id=new.workspace_id and x.condominium_id=new.condominium_id)::int,count(*) filter(where i.direction='Destinazione' and x.lifecycle_status='Attiva' and x.workspace_id=new.workspace_id and x.condominium_id=new.condominium_id)::int into s,d,v,u,a,b from public.condominium_unit_transformation_items i left join public.condominium_units x on x.id=i.unit_id where i.transformation_id=new.id; if s<>new.source_unit_count or d<>new.destination_unit_count or v<>s+d or u<>s+d then raise exception 'UNIT_TRANSFORMATION_GENEALOGY_MISMATCH'; end if; if a<>s or b<>d then raise exception 'UNIT_TRANSFORMATION_UNITS_NOT_ACTIVE'; end if; if new.transformation_type='Fusione' and (s<2 or d<>1) then raise exception 'UNIT_TRANSFORMATION_FUSION_GENEALOGY_INVALID'; end if; if new.transformation_type='Frazionamento' and (s<>1 or d<2) then raise exception 'UNIT_TRANSFORMATION_SPLIT_GENEALOGY_INVALID'; end if; return new; end $$;
create or replace function public.validate_condominium_work_scope() returns trigger language plpgsql set search_path='' as $$ declare w uuid; a timestamptz; begin select workspace_id,archived_at into w,a from public.condominiums where id=new.condominium_id; if w is null then raise exception 'Condominio non trovato'; end if; if new.workspace_id<>w then raise exception 'Workspace del lavoro non coerente con il condominio'; end if; if a is not null then raise exception 'Non è possibile modificare lavori di un condominio archiviato'; end if; return new; end $$;
create or replace function public.validate_condominium_work_reference_scope() returns trigger language plpgsql set search_path='' as $$ begin if new.fund_id is not null and not exists(select 1 from public.condominium_funds f where f.id=new.fund_id and f.workspace_id=new.workspace_id and f.condominium_id=new.condominium_id) then raise exception 'Fondo non coerente con il lavoro'; end if; if new.supplier_id is not null and not exists(select 1 from public.condominium_suppliers s where s.id=new.supplier_id and s.workspace_id=new.workspace_id and s.condominium_id=new.condominium_id) then raise exception 'Fornitore non coerente con il lavoro'; end if; if new.register_item_id is not null and not exists(select 1 from public.condominium_register_items r where r.id=new.register_item_id and r.workspace_id=new.workspace_id and r.condominium_id=new.condominium_id) then raise exception 'Voce registro non coerente con il lavoro'; end if; return new; end $$;
create or replace function public.validate_condominium_work_child_scope() returns trigger language plpgsql security definer set search_path='' as $$ declare w uuid;c uuid;a timestamptz;dw uuid;dc uuid;begin select x.workspace_id,x.condominium_id,o.archived_at into w,c,a from public.condominium_works x join public.condominiums o on o.id=x.condominium_id where x.id=new.work_id; if w is null then raise exception 'Lavoro non trovato'; end if; if new.workspace_id<>w or new.condominium_id<>c then raise exception 'Workspace/condominio non coerenti con il lavoro'; end if; if a is not null then raise exception 'Non è possibile modificare dati di un lavoro archiviato'; end if; if new.document_id is not null then select d.workspace_id,d.condominium_id into dw,dc from public.documents d where d.legacy_id=new.document_id; if not found or dw<>new.workspace_id or dc is distinct from new.condominium_id then raise exception 'Il documento collegato al lavoro deve appartenere allo stesso workspace e condominio'; end if; end if; return new; end $$;
create or replace function public.validate_condominium_work_financial_scope() returns trigger language plpgsql set search_path='' as $$ declare w uuid;c uuid;begin select workspace_id,condominium_id into w,c from public.condominium_works where id=new.work_id; if new.ledger_entry_id is not null and not exists(select 1 from public.condominium_ledger_entries where id=new.ledger_entry_id and workspace_id=w and condominium_id=c) then raise exception 'Movimento contabile non coerente con il lavoro'; end if; if new.payment_entry_id is not null and not exists(select 1 from public.condominium_ledger_entries where id=new.payment_entry_id and workspace_id=w and condominium_id=c) then raise exception 'Movimento di pagamento non coerente con il lavoro'; end if; return new; end $$;
create or replace function public.validate_condominium_work_progress_accounting_links() returns trigger language plpgsql security definer set search_path='' as $$ declare w record;l record;p record;begin select workspace_id,condominium_id,supplier_id into w from public.condominium_works where id=new.work_id; if not found then raise exception 'Lavoro collegato al SAL non trovato'; end if; if new.ledger_entry_id is not null then select workspace_id,condominium_id,direction,supplier_id into l from public.condominium_ledger_entries where id=new.ledger_entry_id; if not found or l.workspace_id<>w.workspace_id or l.condominium_id<>w.condominium_id then raise exception 'Movimento contabile non coerente con il lavoro'; end if; if l.direction<>'Uscita' then raise exception 'Il movimento contabile della spesa deve essere un''Uscita'; end if; if w.supplier_id is not null and l.supplier_id is not null and w.supplier_id<>l.supplier_id then raise exception 'Il fornitore del movimento contabile non coincide con quello del lavoro'; end if; end if; if new.payment_entry_id is not null then if new.ledger_entry_id is not null and new.payment_entry_id=new.ledger_entry_id then raise exception 'Il movimento di pagamento deve essere distinto dal movimento della spesa'; end if; select workspace_id,condominium_id,direction,supplier_id,amount into p from public.condominium_ledger_entries where id=new.payment_entry_id; if not found or p.workspace_id<>w.workspace_id or p.condominium_id<>w.condominium_id then raise exception 'Movimento di pagamento non coerente con il lavoro'; end if; if p.direction<>'Uscita' then raise exception 'Il movimento di pagamento deve essere un''Uscita'; end if; if w.supplier_id is not null and p.supplier_id is not null and w.supplier_id<>p.supplier_id then raise exception 'Il fornitore del pagamento non coincide con quello del lavoro'; end if; if coalesce(new.paid_amount,0)>coalesce(p.amount,0)+0.005 then raise exception 'Il pagato del SAL supera l''importo del movimento di pagamento collegato'; end if; end if; return new; end $$;
create or replace function public.sync_condominium_work_financial_summary(p_work_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare a numeric:=0;p numeric:=0;q numeric:=0;s text:='Nessun importo';begin if p_work_id is null then return;end if;perform 1 from public.condominium_works where id=p_work_id for update;if not found then return;end if;select coalesce(sum(amount),0),coalesce(sum(paid_amount),0),coalesce((select percentage from public.condominium_work_progress where work_id=p_work_id order by progress_date desc,progress_no desc,created_at desc limit 1),0) into a,p,q from public.condominium_work_progress where work_id=p_work_id;p:=least(greatest(round(p,2),0),round(a,2));if a<=0 then s:='Nessun importo';elsif p>=a-0.005 then s:='Pagato';elsif p>0 then s:='Parzialmente pagato';else s:='Da pagare';end if;update public.condominium_works set actual_amount=round(a,2),paid_amount=p,remaining_amount=greatest(round(a-p,2),0),progress_percent=least(greatest(q,0),100),payment_status=s,updated_at=now() where id=p_work_id;end $$;
create or replace function public.sync_condominium_work_financial_summary_trigger() returns trigger language plpgsql security definer set search_path='' as $$ begin if tg_op='DELETE' then perform public.sync_condominium_work_financial_summary(old.work_id);return old;end if;perform public.sync_condominium_work_financial_summary(new.work_id);if tg_op='UPDATE' and old.work_id is distinct from new.work_id then perform public.sync_condominium_work_financial_summary(old.work_id);end if;return new;end $$;
create or replace function public.audit_condominium_work_change() returns trigger language plpgsql security definer set search_path='' as $$ declare ws uuid;co uuid;wid uuid;act text;descr text;dat jsonb:='{}';begin if tg_op='DELETE' then ws:=old.workspace_id;co:=old.condominium_id;wid:=old.id;act:='work_deleted';descr:='Lavoro eliminato';dat:=jsonb_build_object('title',old.title,'status',old.status);elsif tg_op='INSERT' then ws:=new.workspace_id;co:=new.condominium_id;wid:=new.id;act:='work_created';descr:='Lavoro creato';dat:=jsonb_build_object('title',new.title,'status',new.status);else ws:=new.workspace_id;co:=new.condominium_id;wid:=new.id;if old.status is distinct from new.status then act:='work_status_changed';descr:='Stato del lavoro modificato';dat:=jsonb_build_object('old_status',old.status,'new_status',new.status);elsif old.approved_amount is distinct from new.approved_amount or old.estimated_amount is distinct from new.estimated_amount then act:='work_budget_changed';descr:='Importi del lavoro modificati';dat:=jsonb_build_object('old_estimated_amount',old.estimated_amount,'new_estimated_amount',new.estimated_amount,'old_approved_amount',old.approved_amount,'new_approved_amount',new.approved_amount);elsif old.supplier_id is distinct from new.supplier_id then act:='work_supplier_changed';descr:='Fornitore del lavoro modificato';dat:=jsonb_build_object('old_supplier_id',old.supplier_id,'new_supplier_id',new.supplier_id);elsif old.start_date is distinct from new.start_date or old.expected_end_date is distinct from new.expected_end_date or old.actual_end_date is distinct from new.actual_end_date then act:='work_dates_changed';descr:='Date del lavoro modificate';dat:=jsonb_build_object('old_start_date',old.start_date,'new_start_date',new.start_date,'old_expected_end_date',old.expected_end_date,'new_expected_end_date',new.expected_end_date,'old_actual_end_date',old.actual_end_date,'new_actual_end_date',new.actual_end_date);else return new;end if;end if;insert into public.condominium_audit_log(workspace_id,condominium_id,entity_type,entity_id,action,description,data) values(ws,co,'condominium_work',wid,act,descr,dat||jsonb_build_object('actor_user_id',auth.uid(),'recorded_at',now()));if tg_op='DELETE' then return old;end if;return new;end $$;
create or replace function public.audit_condominium_work_progress_change() returns trigger language plpgsql security definer set search_path='' as $$ declare ws uuid;co uuid;wid uuid;pid uuid;act text;descr text;dat jsonb;begin if tg_op='DELETE' then ws:=old.workspace_id;co:=old.condominium_id;wid:=old.work_id;pid:=old.id;act:='work_progress_deleted';descr:='SAL eliminato';dat:=jsonb_build_object('progress_no',old.progress_no,'amount',old.amount,'percentage',old.percentage);elsif tg_op='INSERT' then ws:=new.workspace_id;co:=new.condominium_id;wid:=new.work_id;pid:=new.id;act:='work_progress_created';descr:='SAL registrato';dat:=jsonb_build_object('progress_no',new.progress_no,'amount',new.amount,'paid_amount',new.paid_amount,'percentage',new.percentage);else if old.amount is not distinct from new.amount and old.paid_amount is not distinct from new.paid_amount and old.percentage is not distinct from new.percentage and old.status is not distinct from new.status and old.progress_date is not distinct from new.progress_date and old.title is not distinct from new.title then return new;end if;ws:=new.workspace_id;co:=new.condominium_id;wid:=new.work_id;pid:=new.id;act:='work_progress_changed';descr:='SAL modificato';dat:=jsonb_build_object('old_amount',old.amount,'new_amount',new.amount,'old_paid_amount',old.paid_amount,'new_paid_amount',new.paid_amount,'old_percentage',old.percentage,'new_percentage',new.percentage,'old_status',old.status,'new_status',new.status);end if;insert into public.condominium_audit_log(workspace_id,condominium_id,entity_type,entity_id,action,description,data) values(ws,co,'condominium_work_progress',pid,act,descr,dat||jsonb_build_object('work_id',wid,'actor_user_id',auth.uid(),'recorded_at',now()));if tg_op='DELETE' then return old;end if;return new;end $$;

